/**
 * Hand-traced vector mattes over the unchanged 1536 × 1024 source paintings.
 * These paths carry no replacement character drawing: consumers sample the
 * original WebP through the white paths and subtract `holes` in black.
 * Keep image/matte transforms together and use the supplied source-space pivot.
 */
export interface PremiumStroke {d: string; width: number}
export interface PremiumMask {
  viewBox: readonly [1536, 1024];
  solidPaths: readonly string[];
  /** Optional broader footprint cleared from the static base before sampling. */
  removalPaths?: readonly string[];
  removalHoles?: readonly string[];
  holes: readonly string[];
  strokes: readonly PremiumStroke[];
  /** Original cast pixels that must remain above the moving scenery. */
  fixedForegroundPaths: readonly string[];
  origin: readonly [number, number];
  recommendedTravel: string;
}

